function renderHomeAtlasPreview(){
 renderHomeAtlasProgress();
 const c=document.getElementById('homeAtlasCanvas');
 if(!c||!c.getContext)return;
 const box=c.getBoundingClientRect(),dpr=(window.ARCHED_PERFORMANCE109?.pixelRatio||Math.min(devicePixelRatio||1,2));
 if(box.width<10||box.height<10)return;
 c.width=Math.round(box.width*dpr);c.height=Math.round(box.height*dpr);
 const g=c.getContext('2d');g.setTransform(dpr,0,0,dpr,0,0);
 const W=box.width,H=box.height;
 g.clearRect(0,0,W,H);
 const rx=-.10,ry=.30,cam=850,cy=Math.cos(ry),sy=Math.sin(ry),cx=Math.cos(rx),sx=Math.sin(rx);
 const raw=new Map(),homeNodes102=[...nodes,...candidateMap.values()];
 homeNodes102.forEach(n=>{
   const x1=n.x*cy-n.z*sy,z1=n.x*sy+n.z*cy,y1=n.y*cx-z1*sx,z2=n.y*sx+z1*cx,p=cam/(cam-z2);
   raw.set(n.id,{x:x1*p,y:y1*p,z:z2});
 });
 const vals=[...raw.values()],xs=vals.map(p=>p.x),ys=vals.map(p=>p.y);
 const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);
 const scale=Math.min((W-34)/Math.max(1,maxX-minX),(H-28)/Math.max(1,maxY-minY))*.94;
 const pts=new Map();
 raw.forEach((p,id)=>pts.set(id,{x:W/2+(p.x-(minX+maxX)/2)*scale,y:H/2+(p.y-(minY+maxY)/2)*scale,z:p.z}));
 const known=n=>structural(n)||mp(n)>0||discovered.has(n.id);
 g.lineWidth=.7;
 edges.forEach(e=>{
   const a=nodeMap.get(e.a),b=nodeMap.get(e.b),pa=pts.get(e.a),pb=pts.get(e.b);
   if(!a||!b||!pa||!pb)return;
   const active=known(a)&&known(b)&&!(structural(a)&&structural(b));
   const fact=a.kind==='fact'||b.kind==='fact';
   if(fact && !active && !['bridge','entity','prerequisite','hierarchy'].includes(e.type))return;
   g.strokeStyle=active?'rgba(107,221,255,.48)':fact?'rgba(100,149,197,.025)':'rgba(95,151,202,.09)';
   g.globalAlpha=active?Math.min(nodeGlow(a),nodeGlow(b))*.92+.08:1;
   g.beginPath();g.moveTo(pa.x,pa.y);g.lineTo(pb.x,pb.y);g.stroke();
 });
 g.globalAlpha=1;
 const sorted=[...homeNodes102].sort((a,b)=>(raw.get(a.id)?.z||0)-(raw.get(b.id)?.z||0));
 sorted.forEach(n=>{
   const p=pts.get(n.id); if(!p)return;
   const score=mp(n),unlocked=discovered.has(n.id);
   let r=1,fill='rgba(91,133,176,.26)',glow=0;
   if(n.kind==='major'){r=4.1;fill='rgba(97,193,237,.72)';glow=7}
   else if(n.kind==='core'){r=5;fill='rgba(105,207,255,.85)';glow=10}
   else if(score>0){const strength=nodeGlow(n);r=2+score/55;fill=`rgba(235,249,255,${(.12+.84*strength).toFixed(3)})`;glow=(7+score/10)*strength}
   else if(unlocked&&n.kind==='frontier'){const strength=nodeGlow(n);r=2.1;fill=`rgba(255,209,102,${(.14+.8*strength).toFixed(3)})`;glow=12*strength}
   else if(unlocked){const strength=nodeGlow(n);r=2.2;fill=`rgba(103,232,249,${(.14+.8*strength).toFixed(3)})`;glow=10*strength}
   else if(n.kind==='bridge'||n.kind==='entity'){r=1.65;fill='rgba(105,162,207,.31)'}
   g.fillStyle=fill;g.shadowColor=fill;g.shadowBlur=glow;
   g.beginPath();g.arc(p.x,p.y,r,0,Math.PI*2);g.fill();
 });
 g.shadowBlur=0;
 const fb=document.querySelector('.atlas-fallback'); if(fb)fb.style.opacity='0';
}
