/* ---------- v18 self-check ----------
   Lets the user verify the core site in the deployed build.
*/
async function runSiteHealth(){
 const checks=[];

 function add(name,ok,detail,status){
   checks.push({name,ok,detail,status:status||(ok?'pass':'fail')});
 }

 try{
   add('App data',Array.isArray(nodes)&&nodes.length===DATA.meta.totalNodes,
       `${nodes.length} nodes loaded`);
 }catch(e){add('App data',false,String(e))}

 try{
   const pool=practicePool('General Knowledge');
   add('Practice',Array.isArray(pool)&&pool.length>0,
       `${pool.length} verified concepts available`);
 }catch(e){add('Practice',false,String(e))}

 try{
   const c=document.getElementById('atlasCanvas');
   add('Knowledge Atlas',!!c&&typeof draw==='function',
       c?`${DATA.meta.relations.toLocaleString()} semantic links ready`:'Canvas missing');
 }catch(e){add('Knowledge Atlas',false,String(e))}

 try{
   const key='arched_health_test';
   (window.archedStorage109||localStorage).setItem(key,'1');
   const ok=(window.archedStorage109||localStorage).getItem(key)==='1';
   (window.archedStorage109||localStorage).removeItem(key);
   add('Local progress',ok,ok?'Browser progress storage ready':'Storage unavailable');
 }catch(e){add('Local progress',false,'Browser storage blocked')}

 const runtimeErrors=(window.__archedHealthErrors||[]).filter(Boolean);
 add('JavaScript runtime',runtimeErrors.length===0,
     runtimeErrors.length?runtimeErrors[0]:'No runtime errors detected');

 // Live presence is a network feature: useful, but not required for core learning.
 try{
   const r=await fetch('/.netlify/functions/live',{method:'GET',cache:'no-store'});
   if(r.ok){
     const j=await r.json();
     add('Live learners',true,`${Number(j.active)||0} active now`,'pass');
   }else add('Live learners',true,'Core works; live endpoint not responding','warn');
 }catch(e){
   add('Live learners',true,'Core works; live only activates on Netlify','warn');
 }

 const core=checks.filter(x=>x.name!=='Live learners');
 const coreOK=core.every(x=>x.ok);
 const btn=document.getElementById('healthButton');
 const label=document.getElementById('healthLabel');
 if(btn){
   btn.classList.toggle('ok',coreOK);
   btn.classList.toggle('bad',!coreOK);
 }
 if(label)label.textContent=coreOK?'Core ready':'Needs attention';

 const list=document.getElementById('healthList');
 if(list){
   list.innerHTML=checks.map(x=>`<div class="health-item-v18"><b>${x.name}</b><span class="${x.status}">${x.status==='pass'?'Ready':x.status==='warn'?'Optional':'Check'} · ${x.detail}</span></div>`).join('');
 }
 return {coreOK,checks};
}

