function pNorm(x){return String(x??'').toLowerCase().normalize('NFKD').replace(/[^\p{L}\p{N}]+/gu,' ').trim()}
function pHash(str){let h=2166136261;for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(36)}
function pRng(seed){let a=parseInt(pHash(String(seed)),36)||1;return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function pShuffle(arr,rng){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function pAnswerType(a){
 const t=String(a||'').trim();
 if(/^\d{3,4}([–—-]\d{2,4})?$/.test(t))return'year';
 if(t.includes('→'))return'sequence';
 if(/^[A-ZÀ-Ý][^,;]{1,55}$/.test(t)&&t.split(/\s+/).length<=6)return'proper';
 if(t.length>75)return'long';
 return'term';
}
