MUSEUM45_QUESTIONS.push(...[{"id":"ADD45-Q11580","qid":11580,"nodeId":"ART50-001","relatedNodeIds":["ART50-001"],"major":"Art History","group":"Italian painting","imageId":"ART50-001","stem":"Which artist painted the work shown?","choices":["Pontormo","Andrea del Sarto","Rosso Fiorentino","Lorenzo Lotto","Perugino"],"correctIndex":0,"answer":"Pontormo","explanation":"Supper at Emmaus is by Pontormo. Recognition of Christ through the breaking of bread; commissioned for the Galluzzo Charterhouse.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/pontormo-supper-emmaus"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"46cb7148a9871277ad08"},{"id":"ADD45-Q11581","qid":11581,"nodeId":"ART50-002","relatedNodeIds":["ART50-002"],"major":"Art History","group":"Italian painting","imageId":"ART50-002","stem":"Which artist painted the work shown?","choices":["Rosso Fiorentino","Pontormo","Lorenzo Lotto","Perugino","Correggio"],"correctIndex":1,"answer":"Pontormo","explanation":"Madonna with Child and the young Saint John is by Pontormo. An unfinished painting: compare its bright colours and figures with Leonardo and Michelangelo.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/madonna-with-child-and-the-young-saint-john"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"e96fb5a63bbde150ad85"},{"id":"ADD45-Q11582","qid":11582,"nodeId":"ART50-003","relatedNodeIds":["ART50-003"],"major":"Art History","group":"Italian painting","imageId":"ART50-003","stem":"Which artist painted the work shown?","choices":["Lorenzo Lotto","Perugino","Andrea del Sarto","Correggio","Cima da Conegliano"],"correctIndex":2,"answer":"Andrea del Sarto","explanation":"Madonna of the Harpies is by Andrea del Sarto. Pyramidal composition and sculptural figures connect the Florentine High Renaissance to Raphael and Michelangelo.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/andrea-del-sarto-harpies"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"069178ac9a328396d563"},{"id":"ADD45-Q11583","qid":11583,"nodeId":"ART50-004","relatedNodeIds":["ART50-004"],"major":"Art History","group":"Italian painting","imageId":"ART50-004","stem":"Which artist painted the work shown?","choices":["Perugino","Correggio","Cima da Conegliano","Rosso Fiorentino","Giorgio Vasari"],"correctIndex":3,"answer":"Rosso Fiorentino","explanation":"Spedalingo Altarpiece (Enthroned Madonna and Child with four saints) is by Rosso Fiorentino. The patron rejected the saints; their identities were changed when the painting was reassigned.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/rosso-fiorentino-madonna-and-child"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"98f2df27cfbf429e31ac"},{"id":"ADD45-Q11584","qid":11584,"nodeId":"ART50-005","relatedNodeIds":["ART50-005"],"major":"Art History","group":"Italian painting","imageId":"ART50-005","stem":"Which artist painted the work shown?","choices":["Correggio","Cima da Conegliano","Giorgio Vasari","Dosso Dossi","Rosso Fiorentino"],"correctIndex":4,"answer":"Rosso Fiorentino","explanation":"Moses Defends the Daughters of Jethro is by Rosso Fiorentino. Learn to distinguish Rosso’s biblical subject and dramatic figure composition from other Florentine paintings.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/rosso-fiorentino-moses"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"8a655b4b56d4f2b54d07"},{"id":"ADD45-Q11585","qid":11585,"nodeId":"ART50-006","relatedNodeIds":["ART50-006"],"major":"Art History","group":"Italian painting","imageId":"ART50-006","stem":"Which artist painted the work shown?","choices":["Lorenzo Lotto","Cima da Conegliano","Giorgio Vasari","Dosso Dossi","Sodoma"],"correctIndex":0,"answer":"Lorenzo Lotto","explanation":"Susanna and the Elders is by Lorenzo Lotto. A biblical narrative of false accusation: connect the subject to Lotto rather than confusing it with later versions.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/susanna-and-the-elders"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"5aaabb6569e82c5c7a11"},{"id":"ADD45-Q11586","qid":11586,"nodeId":"ART50-007","relatedNodeIds":["ART50-007"],"major":"Art History","group":"Italian painting","imageId":"ART50-007","stem":"Which artist painted the work shown?","choices":["Giorgio Vasari","Perugino","Dosso Dossi","Sodoma","Giulio Romano"],"correctIndex":1,"answer":"Perugino","explanation":"Pietà is by Perugino. Distinguish this painted Pietà from Michelangelo’s sculpture and from other depictions of mourning over Christ.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/pieta-perugino-uffizi-en"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"d8cdcfec1de8ddc5e540"},{"id":"ADD45-Q11587","qid":11587,"nodeId":"ART50-008","relatedNodeIds":["ART50-008"],"major":"Art History","group":"Italian painting","imageId":"ART50-008","stem":"Which artist painted the work shown?","choices":["Dosso Dossi","Sodoma","Correggio","Giulio Romano","Federico Barocci"],"correctIndex":2,"answer":"Correggio","explanation":"Adoration of the Christ Child is by Correggio. Link the devotional subject to Correggio and the Emilian Renaissance.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/correggio-virgin-adoring-child"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"0f497e6e2bb4ee3aaf0c"},{"id":"ADD45-Q11588","qid":11588,"nodeId":"ART50-009","relatedNodeIds":["ART50-009"],"major":"Art History","group":"Italian painting","imageId":"ART50-009","stem":"Which artist painted the work shown?","choices":["Sodoma","Giulio Romano","Federico Barocci","Cima da Conegliano","Mariotto Albertinelli"],"correctIndex":3,"answer":"Cima da Conegliano","explanation":"St Jerome in the Desert is by Cima da Conegliano. Associate the saint and the landscape with Cima; this work is in the Uffizi, not the Pitti Palace.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/st-jerome-in-the-desert-928f704d-a885-43d6-8671-88163e9b4672"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"fa9863cfe23880bfed1f"},{"id":"ADD45-Q11589","qid":11589,"nodeId":"ART50-010","relatedNodeIds":["ART50-010"],"major":"Art History","group":"Italian painting","imageId":"ART50-010","stem":"Which artist painted the work shown?","choices":["Giulio Romano","Federico Barocci","Mariotto Albertinelli","Fra Bartolomeo","Correggio"],"correctIndex":4,"answer":"Correggio","explanation":"Rest on the Flight into Egypt with St Francis is by Correggio. The added saint distinguishes this version of the Holy Family’s journey from similarly titled paintings.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/correggio-rest-on-the-flight-into-egypt"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"774954aff3600fb9068c"},{"id":"ADD45-Q11590","qid":11590,"nodeId":"ART50-011","relatedNodeIds":["ART50-011"],"major":"Art History","group":"Italian painting","imageId":"ART50-011","stem":"Which artist painted the work shown?","choices":["Andrea del Sarto","Federico Barocci","Mariotto Albertinelli","Fra Bartolomeo","Sebastiano del Piombo"],"correctIndex":0,"answer":"Andrea del Sarto","explanation":"Assumption of the Virgin (Assunta Passerini) is by Andrea del Sarto. Keep the Passerini altarpiece and its Pitti collection separate from Andrea del Sarto’s Uffizi works.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Pitti Palace · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/assumption-of-the-virgin-assunta-passerini"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"672668c7fb20889625bd"},{"id":"ADD45-Q11591","qid":11591,"nodeId":"ART50-012","relatedNodeIds":["ART50-012"],"major":"Art History","group":"Italian painting","imageId":"ART50-012","stem":"Which artist painted the work shown?","choices":["Mariotto Albertinelli","Giorgio Vasari","Fra Bartolomeo","Sebastiano del Piombo","Piero di Cosimo"],"correctIndex":1,"answer":"Giorgio Vasari","explanation":"Portrait of Lorenzo de’ Medici is by Giorgio Vasari. Vasari was a painter as well as the author of artists’ biographies; connect the portrait to Medici patronage.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/vasari-lorenzo-de-medici-portrait"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"8a2cf00ae0a2a254c4ff"},{"id":"ADD45-Q11592","qid":11592,"nodeId":"ART50-013","relatedNodeIds":["ART50-013"],"major":"Art History","group":"Italian painting","imageId":"ART50-013","stem":"Which artist painted the work shown?","choices":["Fra Bartolomeo","Sebastiano del Piombo","Giorgio Vasari","Piero di Cosimo","Bronzino"],"correctIndex":2,"answer":"Giorgio Vasari","explanation":"Portrait of Alessandro de’ Medici is by Giorgio Vasari. Distinguish the sitter from Lorenzo de’ Medici; attribution and political portraiture are separate learning targets.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/vasari-alessandro-portrait"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"0b1fe61624ad2f2d1661"},{"id":"ADD45-Q11593","qid":11593,"nodeId":"ART50-014","relatedNodeIds":["ART50-014"],"major":"Art History","group":"Italian painting","imageId":"ART50-014","stem":"Which artist painted the work shown?","choices":["Sebastiano del Piombo","Piero di Cosimo","Bronzino","Dosso Dossi","Garofalo"],"correctIndex":3,"answer":"Dosso Dossi","explanation":"St John the Baptist is by Dosso Dossi. Extend Renaissance recognition beyond Florence and Venice to the Ferrarese painter Dosso Dossi.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Pitti Palace · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/dosso-baptist"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"39ef4e22a4880fe017aa"},{"id":"ADD45-Q11594","qid":11594,"nodeId":"ART50-015","relatedNodeIds":["ART50-015"],"major":"Art History","group":"Italian painting","imageId":"ART50-015","stem":"Which artist painted the work shown?","choices":["Piero di Cosimo","Bronzino","Garofalo","Giovanni Bellini","Sodoma"],"correctIndex":4,"answer":"Sodoma","explanation":"St Sebastian’s processional gonfalon is by Sodoma. A processional banner has two painted sides: the martyrdom and a Virgin and Child with saints.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/sodoma-st-sebastian"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"8f9d4cb18e88c18c23de"},{"id":"ADD45-Q11595","qid":11595,"nodeId":"ART50-016","relatedNodeIds":["ART50-016"],"major":"Art History","group":"Italian painting","imageId":"ART50-016","stem":"Which artist painted the work shown?","choices":["Giulio Romano","Bronzino","Garofalo","Giovanni Bellini","Pisanello"],"correctIndex":0,"answer":"Giulio Romano","explanation":"Virgin and Child is by Giulio Romano. Distinguish this Giulio Romano panel from the many similarly titled works by other Renaissance painters.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/giulio-romano-virgin-and-child"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"6e6aa14ba67d78dde1fa"},{"id":"ADD45-Q11596","qid":11596,"nodeId":"ART50-017","relatedNodeIds":["ART50-017"],"major":"Art History","group":"Italian painting","imageId":"ART50-017","stem":"Which artist painted the work shown?","choices":["Garofalo","Federico Barocci","Giovanni Bellini","Pisanello","Carlo Crivelli"],"correctIndex":1,"answer":"Federico Barocci","explanation":"Madonna of the Cat is by Federico Barocci. Recognise Barocci’s domestic devotional subject without reducing study to memorising a century.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Pitti Palace · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/barocci-madonna-cat"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"aa0d297c5a829bb27501"},{"id":"ADD45-Q11597","qid":11597,"nodeId":"ART50-018","relatedNodeIds":["ART50-018"],"major":"Art History","group":"Italian painting","imageId":"ART50-018","stem":"Which artist painted the work shown?","choices":["Giovanni Bellini","Pisanello","Mariotto Albertinelli","Carlo Crivelli","Francesco Hayez"],"correctIndex":2,"answer":"Mariotto Albertinelli","explanation":"Visitation is by Mariotto Albertinelli. The meeting of Mary and Elizabeth distinguishes the Visitation from the Annunciation.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/albertinelli-visitation"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"126012dbf69fcde974c2"},{"id":"ADD45-Q11598","qid":11598,"nodeId":"ART50-019","relatedNodeIds":["ART50-019"],"major":"Art History","group":"Italian painting","imageId":"ART50-019","stem":"Which artist painted the work shown?","choices":["Pisanello","Carlo Crivelli","Francesco Hayez","Fra Bartolomeo","Pontormo"],"correctIndex":3,"answer":"Fra Bartolomeo","explanation":"Holy Conversation (Mystic Marriage of St Catherine / Pitti Panel) is by Fra Bartolomeo. Connect the sacred conversation and Saint Catherine to Fra Bartolomeo; keep this Pitti panel distinct from other versions.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Pitti Palace · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/holy-conversation-fra-bartolomeo"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"a04582d9db3f622d6069"},{"id":"ADD45-Q11599","qid":11599,"nodeId":"ART50-020","relatedNodeIds":["ART50-020"],"major":"Art History","group":"Italian painting","imageId":"ART50-020","stem":"Which artist painted the work shown?","choices":["Carlo Crivelli","Francesco Hayez","Pontormo","Andrea del Sarto","Sebastiano del Piombo"],"correctIndex":4,"answer":"Sebastiano del Piombo","explanation":"Martyrdom of St Agatha is by Sebastiano del Piombo. Broaden Renaissance attribution to Sebastiano del Piombo and distinguish martyrdom narratives.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Pitti Palace · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/martyrdom-of-st-agatha"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"efcec6e9420a65c18281"},{"id":"ADD45-Q11600","qid":11600,"nodeId":"ART50-021","relatedNodeIds":["ART50-021"],"major":"Art History","group":"Italian painting","imageId":"ART50-021","stem":"Which artist painted the work shown?","choices":["Piero di Cosimo","Francesco Hayez","Pontormo","Andrea del Sarto","Rosso Fiorentino"],"correctIndex":0,"answer":"Piero di Cosimo","explanation":"Incarnation of Jesus and Saints is by Piero di Cosimo. Piero di Cosimo is a distinct painter from Piero della Francesca; the record identifies tempera grassa on wood.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/the-incarnation-of-jesus-and-the-saints-philip-benizi-john-the-evangelist-catherine-of-alexandria-margaret-peter-and-antoninus-pierozzi"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"eaf2ef0ebc15e5635367"},{"id":"ADD45-Q11601","qid":11601,"nodeId":"ART50-022","relatedNodeIds":["ART50-022"],"major":"Art History","group":"Italian painting","imageId":"ART50-022","stem":"Which artist painted the work shown?","choices":["Pontormo","Bronzino","Andrea del Sarto","Rosso Fiorentino","Lorenzo Lotto"],"correctIndex":1,"answer":"Bronzino","explanation":"Portrait of Bia de’ Medici is by Bronzino. Learn the Medici child portrait as a Bronzino work; distinguish sitter identification from authorship.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/portrait-of-bia-de-medici"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"a0cd0381559aab18beb7"},{"id":"ADD45-Q11602","qid":11602,"nodeId":"ART50-023","relatedNodeIds":["ART50-023"],"major":"Art History","group":"Italian painting","imageId":"ART50-023","stem":"Which artist painted the work shown?","choices":["Andrea del Sarto","Rosso Fiorentino","Garofalo","Lorenzo Lotto","Perugino"],"correctIndex":2,"answer":"Garofalo","explanation":"Annunciation is by Garofalo. Extend attribution to the Ferrarese Renaissance; keep Garofalo’s version separate from Leonardo’s and Crivelli’s.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/garofalo-annunciation"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"f45840cb9ca52c8eee4a"},{"id":"ADD45-Q11603","qid":11603,"nodeId":"ART50-024","relatedNodeIds":["ART50-024"],"major":"Art History","group":"Italian painting","imageId":"ART50-024","stem":"Which artist painted the work shown?","choices":["Rosso Fiorentino","Lorenzo Lotto","Perugino","Giovanni Bellini","Correggio"],"correctIndex":3,"answer":"Giovanni Bellini","explanation":"Doge Leonardo Loredan is by Giovanni Bellini. The ruler of Venice is shown in three-quarter view; oil paint makes the flesh and ceremonial robes appear lifelike.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"National Gallery, London · collection record","page":null,"verificationUrl":"https://www.nationalgallery.org.uk/paintings/giovanni-bellini-doge-leonardo-loredan"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"5f0f4b53611e9ffdb479"},{"id":"ADD45-Q11604","qid":11604,"nodeId":"ART50-025","relatedNodeIds":["ART50-025"],"major":"Art History","group":"Italian painting","imageId":"ART50-025","stem":"Which artist painted the work shown?","choices":["Lorenzo Lotto","Perugino","Correggio","Cima da Conegliano","Pisanello"],"correctIndex":4,"answer":"Pisanello","explanation":"The Vision of Saint Eustace is by Pisanello. The saint recognises Christ in a crucifix between a stag’s antlers; detailed animals connect religious narrative with courtly hunting.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"National Gallery, London · collection record","page":null,"verificationUrl":"https://www.nationalgallery.org.uk/paintings/pisanello-the-vision-of-saint-eustace"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"1dc40ce9886bf57293d2"},{"id":"ADD45-Q11605","qid":11605,"nodeId":"ART50-026","relatedNodeIds":["ART50-026"],"major":"Art History","group":"Italian painting","imageId":"ART50-026","stem":"Which artist painted the work shown?","choices":["Carlo Crivelli","Perugino","Correggio","Cima da Conegliano","Giorgio Vasari"],"correctIndex":0,"answer":"Carlo Crivelli","explanation":"The Annunciation, with Saint Emidius is by Carlo Crivelli. Saint Emidius carries a model of Ascoli Piceno; the work links the Annunciation to the town’s self-government.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"National Gallery, London · collection record","page":null,"verificationUrl":"https://www.nationalgallery.org.uk/paintings/carlo-crivelli-the-annunciation-with-saint-emidius"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"615b0ea8933ce8aeede7"},{"id":"ADD45-Q11606","qid":11606,"nodeId":"ART50-027","relatedNodeIds":["ART50-027"],"major":"Art History","group":"Italian painting","imageId":"ART50-027","stem":"Which artist painted the work shown?","choices":["Correggio","Francesco Hayez","Cima da Conegliano","Giorgio Vasari","Dosso Dossi"],"correctIndex":1,"answer":"Francesco Hayez","explanation":"The Kiss (Brera, 1859) is by Francesco Hayez. The Romantic couple carries a Risorgimento message; clothing colours allude to Italy and France. This is the 1859 Brera version.","format":"single_choice","visualSkill":"artist_recognition","references":[{"file":"Pinacoteca di Brera · collection record","page":null,"verificationUrl":"https://pinacotecabrera.org/en/collezioni/collezione-on-line/the-kiss/"}],"examLanguages":["en","it"],"scope":"shared","version":"question-reviewed-v57","fingerprint":"51c72d83b3fc8c19918b"},{"id":"ADD45-Q11607","qid":11607,"nodeId":"ART50-001","relatedNodeIds":["ART50-001"],"major":"Art History","group":"Italian painting","imageId":null,"stem":"In Pontormo’s Supper at Emmaus, which action reveals Christ’s identity?","choices":["Washing the disciples’ feet","Raising Lazarus","Breaking bread","Giving Peter the keys","Entering Jerusalem"],"correctIndex":2,"answer":"Breaking bread","explanation":"The disciples recognise Christ when he breaks bread. The scene is the meal at Emmaus, rather than the Last Supper.","format":"single_choice","visualSkill":"historical_context","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/pontormo-supper-emmaus"}],"examLanguages":["en","it"],"scope":"shared","version":"knowledge-italian-art-v50","fingerprint":"c96172295ec5beff7658"},{"id":"ADD45-Q11608","qid":11608,"nodeId":"ART50-001","relatedNodeIds":["ART50-001"],"major":"Art History","group":"Italian painting","imageId":null,"stem":"Pontormo painted his Supper at Emmaus for which religious community?","choices":["The Sistine Chapel","The Scrovegni Chapel","The Basilica of San Marco in Venice","The Galluzzo Charterhouse","The cathedral chapter of Siena"],"correctIndex":3,"answer":"The Galluzzo Charterhouse","explanation":"The painting was commissioned for the Carthusian monastery at Galluzzo, where Pontormo took refuge during a plague.","format":"single_choice","visualSkill":"historical_context","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/pontormo-supper-emmaus"}],"examLanguages":["en","it"],"scope":"shared","version":"knowledge-italian-art-v50","fingerprint":"694bc647718cfaa3ed3c"},{"id":"ADD45-Q11609","qid":11609,"nodeId":"ART50-003","relatedNodeIds":["ART50-003"],"major":"Art History","group":"Italian painting","imageId":null,"stem":"Which statement about Andrea del Sarto’s Madonna of the Harpies is accurate?","choices":["It is a fresco by Giotto in Padua","It is a marble sculpture by Michelangelo","It depicts the civic government of Ascoli Piceno","It is an Impressionist outdoor scene","It combines a pyramidal composition with sculptural figures"],"correctIndex":4,"answer":"It combines a pyramidal composition with sculptural figures","explanation":"The Uffizi links its composition to Raphael and its monumental figures to Michelangelo. The title refers to figures on the pedestal, whose interpretation is debated.","format":"single_choice","visualSkill":"historical_context","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/andrea-del-sarto-harpies"}],"examLanguages":["en","it"],"scope":"shared","version":"knowledge-italian-art-v50","fingerprint":"0d9a12c8e6eb93c2bb0a"},{"id":"ADD45-Q11610","qid":11610,"nodeId":"ART50-015","relatedNodeIds":["ART50-015"],"major":"Art History","group":"Italian painting","imageId":null,"stem":"Sodoma’s St Sebastian work in the Uffizi was made as which type of object?","choices":["A two-sided processional banner","A ceiling fresco","An illuminated manuscript","A bronze relief","A woven tapestry"],"correctIndex":0,"answer":"A two-sided processional banner","explanation":"The gonfalon is painted on both sides: Sebastian’s martyrdom on one side and the Virgin and Child with saints on the other.","format":"single_choice","visualSkill":"historical_context","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/sodoma-st-sebastian"}],"examLanguages":["en","it"],"scope":"shared","version":"knowledge-italian-art-v50","fingerprint":"33c6c0342770cb0b5404"},{"id":"ADD45-Q11611","qid":11611,"nodeId":"ART50-018","relatedNodeIds":["ART50-018"],"major":"Art History","group":"Italian painting","imageId":null,"stem":"The title Visitation, as in Albertinelli’s painting, refers to which encounter?","choices":["Gabriel announcing Christ’s birth to Mary","Mary meeting Elizabeth","The Magi adoring the Christ Child","Christ meeting the disciples at Emmaus","Thomas touching Christ’s wound"],"correctIndex":1,"answer":"Mary meeting Elizabeth","explanation":"The Visitation represents Mary visiting Elizabeth. It is a different episode from the Annunciation.","format":"single_choice","visualSkill":"historical_context","references":[{"file":"Uffizi Gallery · collection record","page":null,"verificationUrl":"https://www.uffizi.it/en/artworks/albertinelli-visitation"}],"examLanguages":["en","it"],"scope":"shared","version":"knowledge-italian-art-v50","fingerprint":"cd5207f515513fffee0d"},{"id":"ADD45-Q11612","qid":11612,"nodeId":"ART50-024","relatedNodeIds":["ART50-024"],"major":"Art History","group":"Italian painting","imageId":null,"stem":"In Bellini’s Doge Leonardo Loredan, what position did the sitter hold?","choices":["Duke of Milan","Grand Duke of Tuscany","Ruler of the Venetian Republic","King of Naples","Pope in Rome"],"correctIndex":2,"answer":"Ruler of the Venetian Republic","explanation":"Loredan was elected doge of Venice in 1501. His ceremonial robes and cap identify his office.","format":"single_choice","visualSkill":"historical_context","references":[{"file":"National Gallery, London · collection record","page":null,"verificationUrl":"https://www.nationalgallery.org.uk/paintings/giovanni-bellini-doge-leonardo-loredan"}],"examLanguages":["en","it"],"scope":"shared","version":"knowledge-italian-art-v50","fingerprint":"dc12454c36ed28af9b97"},{"id":"ADD45-Q11613","qid":11613,"nodeId":"ART50-024","relatedNodeIds":["ART50-024"],"major":"Art History","group":"Italian painting","imageId":null,"stem":"Which statement correctly describes Bellini’s portrait of Doge Leonardo Loredan?","choices":["The head is shown strictly in profile","The doge is shown on horseback","The work is a fresco in the Doge’s Palace","The head is shown in three-quarter view","The doge wears a papal tiara"],"correctIndex":3,"answer":"The head is shown in three-quarter view","explanation":"Bellini uses a three-quarter view rather than the strict profile common in earlier portraits of Venetian doges. The painting is oil on wood.","format":"single_choice","visualSkill":"historical_context","references":[{"file":"National Gallery, London · collection record","page":null,"verificationUrl":"https://www.nationalgallery.org.uk/paintings/giovanni-bellini-doge-leonardo-loredan"}],"examLanguages":["en","it"],"scope":"shared","version":"knowledge-italian-art-v50","fingerprint":"2c78c9f25014deb855ad"},{"id":"ADD45-Q11614","qid":11614,"nodeId":"ART50-025","relatedNodeIds":["ART50-025"],"major":"Art History","group":"Italian painting","imageId":null,"stem":"Which detail identifies the miraculous vision in Pisanello’s The Vision of Saint Eustace?","choices":["A dove above the Virgin’s head","Keys held by Saint Peter","A broken wheel beside Saint Catherine","Arrows in Saint Sebastian’s body","A crucifix between a stag’s antlers"],"correctIndex":4,"answer":"A crucifix between a stag’s antlers","explanation":"The stag bears a crucifix between its antlers. The vision prompts the huntsman’s conversion to Christianity.","format":"single_choice","visualSkill":"historical_context","references":[{"file":"National Gallery, London · collection record","page":null,"verificationUrl":"https://www.nationalgallery.org.uk/paintings/pisanello-the-vision-of-saint-eustace"}],"examLanguages":["en","it"],"scope":"shared","version":"knowledge-italian-art-v50","fingerprint":"f21735af4a7e3f33744c"},{"id":"ADD45-Q11615","qid":11615,"nodeId":"ART50-026","relatedNodeIds":["ART50-026"],"major":"Art History","group":"Italian painting","imageId":null,"stem":"Which town is represented by the model carried by Saint Emidius in Crivelli’s Annunciation?","choices":["Ascoli Piceno","Venice","Florence","Ferrara","Mantua"],"correctIndex":0,"answer":"Ascoli Piceno","explanation":"Emidius is the patron saint of Ascoli Piceno. The painting also commemorates the town’s grant of self-government.","format":"single_choice","visualSkill":"historical_context","references":[{"file":"National Gallery, London · collection record","page":null,"verificationUrl":"https://www.nationalgallery.org.uk/paintings/carlo-crivelli-the-annunciation-with-saint-emidius"}],"examLanguages":["en","it"],"scope":"shared","version":"knowledge-italian-art-v50","fingerprint":"49e75b0888d0b9784a06"},{"id":"ADD45-Q11616","qid":11616,"nodeId":"ART50-027","relatedNodeIds":["ART50-027"],"major":"Art History","group":"Italian painting","imageId":null,"stem":"Which historical movement helps explain the patriotic meaning of Hayez’s 1859 Kiss?","choices":["The Counter-Reformation","The Risorgimento","The French Revolution of 1789","The Protestant Reformation","The Russian Revolution"],"correctIndex":1,"answer":"The Risorgimento","explanation":"The Romantic painting expresses the hopes of Italian unification. The colours of the couple’s clothing allude to Italy and France.","format":"single_choice","visualSkill":"historical_context","references":[{"file":"Pinacoteca di Brera · collection record","page":null,"verificationUrl":"https://pinacotecabrera.org/en/collezioni/collezione-on-line/the-kiss/"}],"examLanguages":["en","it"],"scope":"shared","version":"knowledge-italian-art-v50","fingerprint":"dce846bfa8046d5fd3db"}]);
