function alternateCuratedStem(stem){
 let m;
 if((m=/^Who designed (.+)\?$/.exec(stem)))return `Which architect designed ${m[1]}?`;
 if((m=/^Which architect designed (.+)\?$/.exec(stem)))return `Who was the architect of ${m[1]}?`;
 if((m=/^Who painted (.+)\?$/.exec(stem)))return `Which artist painted ${m[1]}?`;
 if((m=/^Who wrote (.+)\?$/.exec(stem)))return `Identify the author of ${m[1]}.`;
 if((m=/^Who authored (.+)\?$/.exec(stem)))return `Identify the author of ${m[1]}.`;
 if(/^In which year /.test(stem))return stem.replace(/^In which year /,'In what year ');
 return null;
}
