function renderSpark(){
 const svg=document.getElementById('growthSpark');if(!svg)return;
 const s=personalHistory.length?personalHistory:[{step:0,nodes:0,relations:0}],w=320,h=54,p=4;
 const max=Math.max(1,...s.map(x=>Math.max(x.nodes,x.relations)));
 const X=i=>p+(s.length===1?0:i*(w-2*p)/(s.length-1)),Y=v=>h-p-(v/max)*(h-2*p);
 const pts=s.map((x,i)=>`${X(i)},${Y(x.nodes)}`).join(' ');
 svg.innerHTML=`<polyline points="${pts}" fill="none" stroke="#69e6a6" stroke-width="2"/><polyline points="${pts} ${w-p},${h-p} ${p},${h-p}" fill="rgba(105,230,166,.08)" stroke="none"/>`;
}
function updateGrowthPanel(){
 const p=personalStats();
 const ids={gFacts:p.solved,gNodes:p.solved+p.derived,gRels:p.relations,gBridges:p.bridges,gFrontier:p.frontier,gRejected:withheld};
 for(const [id,v] of Object.entries(ids)){const el=document.getElementById(id);if(el)el.textContent=Number(v).toLocaleString()}
 renderGrowthChart();
}
function renderGrowthChart(){
 const svg=document.getElementById('growthChart');if(!svg)return;
 const s=personalHistory.length?personalHistory:[{step:0,nodes:0,relations:0}],w=520,h=210,pl=38,pr=15,pt=18,pb=28;
 const max=Math.max(1,...s.map(x=>Math.max(x.nodes,x.relations)));
 const X=i=>pl+(s.length===1?0:i*(w-pl-pr)/(s.length-1)),Y=v=>h-pb-(v/max)*(h-pt-pb);
 let grid='';for(let i=0;i<5;i++){const y=pt+i*(h-pt-pb)/4;grid+=`<line x1="${pl}" y1="${y}" x2="${w-pr}" y2="${y}" stroke="rgba(255,255,255,.055)"/>`;}
 const nodesLine=`<polyline points="${s.map((d,i)=>X(i)+','+Y(d.nodes)).join(' ')}" fill="none" stroke="#67e8f9" stroke-width="2.2"/>`;
 const relLine=`<polyline points="${s.map((d,i)=>X(i)+','+Y(d.relations)).join(' ')}" fill="none" stroke="#69e6a6" stroke-width="2.2"/>`;
 const dots=s.map((d,i)=>`<circle cx="${X(i)}" cy="${Y(d.nodes)}" r="${i===s.length-1?4:2.3}" fill="#67e8f9"/>`).join('');
 const step=Math.max(1,Math.ceil(s.length/7));
 const labs=s.map((d,i)=>(i%step===0||i===s.length-1)?`<text x="${X(i)}" y="${h-8}" fill="#7186a4" font-size="9" text-anchor="middle">${d.solved}</text>`:'').join('');
 svg.innerHTML=grid+relLine+nodesLine+dots+labs+`<text x="${pl}" y="12" fill="#67e8f9" font-size="10">personal knowledge nodes</text><text x="${pl+145}" y="12" fill="#69e6a6" font-size="10">active semantic lines</text><text x="${w-pr}" y="${h-8}" fill="#7186a4" font-size="9" text-anchor="end">solved questions →</text>`;
}
